do $$declare ddl text;begin ddl:=pg_get_functiondef('public.copy_schedule_week_with_statuses(uuid[],date)'::regprocedure);ddl:=replace(ddl,$a$from public.schedule_day_statuses where employee_id=any(p_employees) and work_date between p_week-7 and p_week-1 and tag='rest'$a$,$b$from public.schedule_day_statuses ds where ds.employee_id=any(p_employees) and ds.work_date between p_week-7 and p_week-1 and ds.tag='rest'$b$);execute ddl;ddl:=pg_get_functiondef('private.scan_attendance_review()'::regprocedure);ddl:=replace(ddl,$a$else 'Habitual Tardiness — Attendance Review' end$a$,$b$else case when cnt>p.late_count then 'Habitual Tardiness — Attendance Review' else 'Late Arrival — Attendance Review' end end$b$);execute ddl;end $$;
